<?php $fmt=static fn($v)=>\App\Service\FinanceEmployeePaymentService::formatMoney($v); ?>
<div class="ux-summary-strip"><div><strong><?= e($employee['full_name']) ?></strong><?php if(($employee['status']??'')!=='active'): ?> · аккаунт неактивен<?php endif; ?></div><div><?= count($ledger) ?> операций</div></div>
<?php if(empty($ledger)): ?><div class="ux-empty"><strong>Операций нет</strong>По этому сотруднику взаиморасчёты не зарегистрированы.</div>
<?php else: ?><div class="table-scroll"><table class="table"><thead><tr><th>Дата</th><th>Операция</th><th>Источник</th><th>Сумма</th><th>Основание</th><th>Сальдо</th><th>Сотрудник</th></tr></thead><tbody><?php foreach($ledger as $row): $cancelled=($row['status']??'')==='CANCELLED'; ?><tr class="<?= $cancelled?'is-muted':'' ?>"><td><?= e(date('d.m.Y',strtotime($row['operation_date']))) ?></td><td><span class="<?= $row['movement_type']==='PAYMENT'?'badge badge-neutral':'badge badge-ok' ?>"><?= $row['movement_type']==='PAYMENT'?'Выплата':'Возврат' ?></span><?php if($cancelled): ?> <span class="badge badge-danger">Отменено</span><?php endif; ?></td><td><?= $row['source_type']==='BANK'?'Расчётный счёт':'Касса' ?><div class="field-note"><?= e($row['money_account_name']??'') ?></div></td><td class="col-mono"><?= e($fmt($row['amount'])) ?> ₽</td><td><?= e($row['purpose']?:($row['note']?:'—')) ?></td><td class="col-mono"><strong><?= e($fmt($row['running_balance'])) ?> ₽</strong></td><td><form method="post" action="<?= app_url('/company/finance/employee-payments/movements/'.(int)$row['id'].'/reassign') ?>" class="inline-form" data-confirm="Изменить сотрудника у этой операции? Денежная операция останется без изменений."><?= csrfField() ?><select class="field-select field-select-sm" name="employee_user_id" required><?php foreach($employees as $candidate): ?><option value="<?= (int)$candidate['id'] ?>" <?= (int)$candidate['id']===(int)$row['employee_user_id']?'selected':'' ?>><?= e($candidate['full_name']) ?></option><?php endforeach; ?></select><button type="submit" class="btn btn-ghost btn-sm">Исправить</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<div class="field-note" style="margin-top:8px">Исправление сотрудника меняет только принадлежность движения в лицевом счёте. Сумма, дата, источник и сама банковская/кассовая операция не переписываются.</div>
